  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-De-Monde-(Druide).html&quot; title=&quot;Arpenteur de monde&quot;&gt;Arpenteur de monde&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspirant-Naga-(Druide).html&quot; title=&quot;Aspirant naga&quot;&gt;Aspirant naga&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;nagaji&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chamanes-Animaux-(Druide).html&quot; title=&quot;Chamanes animaux&quot;&gt;Chamanes animaux&lt;/a&gt; (MJRA,AG,AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Si la plupart des druides s’occupent des &#233;tendues sauvages, certains choisissent de s’installer dans des villages, o&#249; ils communient avec les animaux et la vermine qui y vivent et parlent au nom d’une nature qui envahit le berceau m&#234;me de la civilisation.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation spontan&#233;e&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_spontan&#233;e_0&quot; href=&quot;#Incantation_spontan&#233;e_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage peut canaliser l’&#233;nergie r&#233;serv&#233;e &#224; un sort pour la transformer spontan&#233;ment en un sort de domaine qu’il n’avait pas pr&#233;par&#233; &#224; l’avance. Il &#171; perd &#187; ce sort et lance &#224; la place un sortil&#232;ge de puissance inf&#233;rieure ou &#233;gale. Cette capacit&#233; remplace celle permettant de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#INCANTATIONSPONTANEE&quot; title=&quot;Le druide&quot;&gt;lancer spontan&#233;ment les sorts de convocation d’alli&#233;s naturels&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pacte avec la nature (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_avec_la_nature_Ext_1&quot; href=&quot;#Pacte_avec_la_nature_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un druide urbain ne peut pas avoir de &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;Les compagnons animaux du druide&quot;&gt;compagnon animal&lt;/a&gt;. Il choisit &#224; la place le domaine auquel il a acc&#232;s parmi ceux de la liste suivante (et non dans celle disponible habituellement pour les druides) : &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Charme.html&quot; title=&quot;Domaine du Charme&quot;&gt;Charme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Communaut&#233;.html&quot; title=&quot;Domaine de la Communaut&#233;&quot;&gt;Communaut&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Connaissance.html&quot; title=&quot;Domaine de la Connaissance&quot;&gt;Connaissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Noblesse.html&quot; title=&quot;Domaine de la Noblesse&quot;&gt;Noblesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Protection.html&quot; title=&quot;Domaine de la Protection&quot;&gt;Protection&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Repos.html&quot; title=&quot;Domaine du Repos&quot;&gt;Repos&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Des-Runes.html&quot; title=&quot;Domaine des Runes&quot;&gt;Runes&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Climat.html&quot; title=&quot;Domaine du Climat&quot;&gt;Climat&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Gardien du savoir (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Gardien_du_savoir_Ext_2&quot; href=&quot;#Gardien_du_savoir_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 2, le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ajoute &#224; sa liste de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tences&lt;/a&gt; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (noblesse), pour lesquelles il re&#231;oit un bonus de +2. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;R&#233;sistance &#224; la tentation (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;sistance_&#224;_la_tentation_Ext_3&quot; href=&quot;#R&#233;sistance_&#224;_la_tentation_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 4, le personnage re&#231;oit un bonus de +2 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#DIVINATION&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;divinations&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#ENCHANTEMENT&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;enchantements&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l’appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mille visages (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mille_visages_Sur_4&quot; href=&quot;#Mille_visages_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un druide urbain re&#231;oit cette &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#MILLEVISAGES&quot; title=&quot;Le druide&quot;&gt;aptitude&lt;/a&gt; au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 6.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Forme animale (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_animale_Sur_5&quot; href=&quot;#Forme_animale_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un druide urbain re&#231;oit cette &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMEANIMALE&quot; title=&quot;Le druide&quot;&gt;aptitude&lt;/a&gt; au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 8 et son niveau effectif sera &#233;gal &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; -4.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Force de l’esprit (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Force_de_l’esprit_Ext_6&quot; href=&quot;#Force_de_l’esprit_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le personnage est immunis&#233; aux effets des &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#ENCHANTEMENT&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;charmes et des coercitions&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#IMMUNITECONTRELEVENIN&quot; title=&quot;Le druide&quot;&gt;immunit&#233; contre le venin&lt;/a&gt;.
